import fs from "node:fs";
import path from "node:path";
import type { Plugin } from "vite";
import {
  buildOverrides,
  mergeTheme,
  parseTheme,
  type ThemeInput,
} from "./theme-css.ts";

// Hand-written baseline: never written by this plugin.
const STYLE_PATH = path.resolve(process.cwd(), "src/styles/style.css");
// Generated by this plugin; must be @import-ed by style.css.
const VARS_PATH = path.resolve(process.cwd(), "src/custom/variables/vars.css");

function readBody(req: import("node:http").IncomingMessage): Promise<string> {
  return new Promise((resolve, reject) => {
    let body = "";
    req.on("data", (c) => (body += c));
    req.on("end", () => resolve(body));
    req.on("error", reject);
  });
}

function readOptional(file: string): string {
  try {
    return fs.readFileSync(file, "utf-8");
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code === "ENOENT") return "";
    throw err;
  }
}

function isThemeInput(value: unknown): value is ThemeInput {
  const isVars = (v: unknown) =>
    typeof v === "object" &&
    v !== null &&
    Object.values(v).every((x) => typeof x === "string");
  return (
    typeof value === "object" &&
    value !== null &&
    isVars((value as ThemeInput).light) &&
    isVars((value as ThemeInput).dark)
  );
}

/**
 * Dev-only middleware for the ThemePanel:
 *   GET  /api/theme -> { light, dark }: baseline (style.css) + overrides (vars.css)
 *   POST /api/theme -> body: { light, dark }, regenerates vars.css with only
 *                      the values that differ from the baseline
 *
 * Never bundled into report output: only active while `vite dev` runs.
 */
export function themeServerPlugin(): Plugin {
  return {
    name: "report-maker:theme-server",
    apply: "serve",
    configureServer(server) {
      server.middlewares.use("/api/theme", async (req, res) => {
        res.setHeader("Content-Type", "application/json");

        if (req.method === "GET") {
          const base = parseTheme(fs.readFileSync(STYLE_PATH, "utf-8"));
          const overrides = parseTheme(readOptional(VARS_PATH));
          res.end(JSON.stringify(mergeTheme(base, overrides)));
          return;
        }

        if (req.method === "POST") {
          try {
            const body: unknown = JSON.parse(await readBody(req));
            if (!isThemeInput(body)) throw new Error("Invalid theme payload");
            const base = parseTheme(fs.readFileSync(STYLE_PATH, "utf-8"));
            fs.mkdirSync(path.dirname(VARS_PATH), { recursive: true });
            fs.writeFileSync(VARS_PATH, buildOverrides(base, body));
            // Vite's watcher picks the change up and HMRs the stylesheet.
            res.end(JSON.stringify({ ok: true }));
          } catch (err) {
            res.statusCode = 400;
            res.end(
              JSON.stringify({
                ok: false,
                error: err instanceof Error ? err.message : String(err),
              }),
            );
          }
          return;
        }

        res.statusCode = 405;
        res.end(JSON.stringify({ ok: false, error: "Method not allowed" }));
      });
    },
  };
}
